def main():
    root_dir = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    public_dir = os.path.join(root_dir, "public", "data", "lesson-plans")
    dist_dir = os.path.join(root_dir, "dist", "data", "lesson-plans")
    os.makedirs(public_dir, exist_ok=True)
    os.makedirs(dist_dir, exist_ok=True)
    
    plans = generate_all_plans()
    
    # ذخیره فایل اصلی کل طرح درس‌ها
    all_path = os.path.join(public_dir, "all-lesson-plans.json")
    with open(all_path, "w", encoding="utf-8") as f:
        json.dump(plans, f, ensure_ascii=False, indent=2)
    print(f"Saved: {all_path} ({len(plans)} plans)")
    
    # ذخیره مجزا به تفکیک پایه
    for grade in range(1, 13):
        g_plans = [p for p in plans if p["grade"] == grade]
        g_path = os.path.join(public_dir, f"grade-{grade}.json")
        with open(g_path, "w", encoding="utf-8") as f:
            json.dump(g_plans, f, ensure_ascii=False, indent=2)
        print(f"  Grade {grade}: {len(g_plans)} plans saved.")
        
    # همگام سازی با dist در صورت وجود
    if os.path.exists(os.path.join(root_dir, "dist")):
        with open(os.path.join(dist_dir, "all-lesson-plans.json"), "w", encoding="utf-8") as f:
            json.dump(plans, f, ensure_ascii=False, indent=2)
        for grade in range(1, 13):
            g_plans = [p for p in plans if p["grade"] == grade]
            with open(os.path.join(dist_dir, f"grade-{grade}.json"), "w", encoding="utf-8") as f:
                json.dump(g_plans, f, ensure_ascii=False, indent=2)
        print("Synchronized lesson plans to dist directory.")

if __name__ == "__main__":
    main()
